svg.script:
const FF_JS = "https:/" + "/cdn.jsdelivr.net/npm/@ffmpeg/ffmpeg@0.11.6/dist/ffmpeg.min.js";
const CORE_JS = "https:/" + "/cdn.jsdelivr.net/npm/@ffmpeg/core-st@0.11.1/dist/ffmpeg-core.js";
const frame = document.getElementById("linux_frame");

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"/>
<style>
  body,html{margin:0;padding:0;background:#000;color:#eee;font-family:monospace;height:100%;display:flex;flex-direction:column;overflow:hidden}
  #bar{padding:8px;background:#1a1a1a;display:flex;gap:8px;align-items:center;border-bottom:1px solid #333;font-size:12px}
  #seek{width:140px;cursor:pointer}
  #cv{flex:1;width:100%;height:100%;object-fit:contain;background:#000}
  #msg{margin-left:auto;color:#7f7}
</style>
<script>
  const OrigWorker = window.Worker;
  window.Worker = function(url, opts) {
    const blob = new Blob(['importScripts("' + url + '");'], { type: "application/javascript" });
    return new OrigWorker(URL.createObjectURL(blob), opts);
  };
<\/script>
<script src="${FF_JS}"><\/script>
</head><body>
<div id="bar">
  <input type="file" id="f" accept=".mkv,.webm,.mp4" disabled />
  <button id="btn">Pause</button>
  <input type="range" id="seek" min="0" max="1000" value="0" disabled />
  <span id="msg">Loading FFmpeg-ST...</span>
</div>
<canvas id="cv"></canvas>
<script>
  const cv = document.getElementById("cv"), ctx = cv.getContext("2d");
  const msg = document.getElementById("msg"), fileIn = document.getElementById("f"), seek = document.getElementById("seek");
  let play = true, runId = 0, ffmpeg = null, actx = null, nextAudioTime = 0, activeSources = [], jumpOffset = -1;

  function stopAudio() {
    activeSources.forEach(s => { try { s.stop(); } catch (_) {} });
    activeSources = [];
    if (actx) nextAudioTime = actx.currentTime;
  }

  document.getElementById("btn").onclick = async () => {
    play = !play;
    document.getElementById("btn").textContent = play ? "Pause" : "Play";
    if (actx) {
      if (play && actx.state === "suspended") await actx.resume();
      else if (!play && actx.state === "running") await actx.suspend();
    }
  };

  (async () => {
    try {
      ffmpeg = FFmpeg.createFFmpeg({ corePath: "${CORE_JS}", mainName: "main", log: false });
      await ffmpeg.load();
      fileIn.disabled = false;
      msg.textContent = "FFmpeg-ST Ready (Select .mkv)";
    } catch (e) {
      msg.textContent = "Load ERR: " + e.message;
    }
  })();

  function findClusterPos(u8, from) {
    for (let i = from; i < u8.length - 4; i++) {
      if (u8[i] === 0x1F && u8[i + 1] === 0x43 && u8[i + 2] === 0xB6 && u8[i + 3] === 0x75) return i;
    }
    return -1;
  }

  function scheduleAudio(pcmBytes) {
    if (!pcmBytes || pcmBytes.byteLength < 16) return 0;
    if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 48000 });
    if (actx.state === "suspended" && play) actx.resume();

    const sr = actx.sampleRate;
    const samples = Math.floor(pcmBytes.byteLength / 8);
    const f32 = new Float32Array(pcmBytes.buffer, pcmBytes.byteOffset, samples * 2);
    const abuf = actx.createBuffer(2, samples, sr);
    const L = abuf.getChannelData(0), R = abuf.getChannelData(1);
    for (let i = 0; i < samples; i++) { L[i] = f32[i * 2]; R[i] = f32[i * 2 + 1]; }

    const src = actx.createBufferSource();
    src.buffer = abuf;
    src.connect(actx.destination);
    const startAt = Math.max(actx.currentTime + 0.05, nextAudioTime);
    src.start(startAt);
    nextAudioTime = startAt + abuf.duration;
    activeSources.push(src);
    src.onended = () => { activeSources = activeSources.filter(x => x !== src); };
    return abuf.duration;
  }

  fileIn.onchange = async (e) => {
    const file = e.target.files ? e.target.files.item(0) : null;
    if (!file || !ffmpeg) return;
    const myRun = ++runId;
    stopAudio();
    play = true;
    document.getElementById("btn").textContent = "Pause";
    if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 48000 });
    nextAudioTime = actx.currentTime;
    const sr = actx.sampleRate;

    const headProbe = new Uint8Array(await file.slice(0, 524288).arrayBuffer());
    const firstCluster = findClusterPos(headProbe, 0);
    if (firstCluster < 0) { msg.textContent = "Invalid MKV: No Cluster found"; return; }
    const mkvHeader = headProbe.subarray(0, firstCluster);

    seek.disabled = false;
    seek.oninput = () => {
      jumpOffset = firstCluster + Math.floor((seek.value / 1000) * (file.size - firstCluster));
    };

    const W = 480, H = 270;
    cv.width = W; cv.height = H;
    const imgData = ctx.createImageData(W, H);
    const TARGET_CHUNK = 1.5 * 1024 * 1024;
    let offset = firstCluster, drawn = 0;

    while (myRun === runId && offset < file.size) {
      if (jumpOffset >= 0) {
        offset = jumpOffset;
        jumpOffset = -1;
        stopAudio();
      }
      if (!play) { await new Promise(r => setTimeout(r, 50)); continue; }

      const startProbe = new Uint8Array(await file.slice(offset, Math.min(file.size, offset + 4 * 1024 * 1024)).arrayBuffer());
      const startRel = findClusterPos(startProbe, 0);
      if (startRel < 0) { offset += 4 * 1024 * 1024; continue; }
      const alignedStart = offset + startRel;

      let alignedEnd = file.size;
      if (alignedStart + TARGET_CHUNK < file.size) {
        const endProbe = new Uint8Array(await file.slice(alignedStart + TARGET_CHUNK, Math.min(file.size, alignedStart + TARGET_CHUNK + 4 * 1024 * 1024)).arrayBuffer());
        const endRel = findClusterPos(endProbe, 0);
        alignedEnd = endRel >= 0 ? (alignedStart + TARGET_CHUNK + endRel) : file.size;
      }

      const pct = ((alignedStart / file.size) * 100).toFixed(1);
      seek.value = Math.floor(((alignedStart - firstCluster) / (file.size - firstCluster)) * 1000);
      msg.textContent = "Buffering @ " + pct + "%...";

      const clusterBytes = new Uint8Array(await file.slice(alignedStart, alignedEnd).arrayBuffer());
      const combined = new Uint8Array(mkvHeader.length + clusterBytes.length);
      combined.set(mkvHeader, 0);
      combined.set(clusterBytes, mkvHeader.length);

      try { ffmpeg.FS("unlink", "part.mkv"); } catch (_) {}
      try { ffmpeg.FS("unlink", "out.rgba"); } catch (_) {}
      try { ffmpeg.FS("unlink", "out.pcm"); } catch (_) {}
      ffmpeg.FS("writeFile", "part.mkv", combined);

      try {
        await ffmpeg.run(
          "-i", "part.mkv", "-sn",
          "-map", "0:v:0", "-vf", "scale=" + W + ":" + H, "-r", "24", "-f", "rawvideo", "-pix_fmt", "rgba", "out.rgba",
          "-map", "0:a:0?", "-ac", "2", "-ar", sr.toString(), "-f", "f32le", "out.pcm"
        );
      } catch (_) {}

      try { ffmpeg.FS("unlink", "part.mkv"); } catch (_) {}
      let raw = null, pcm = null;
      try { raw = ffmpeg.FS("readFile", "out.rgba"); } catch (_) {}
      try { pcm = ffmpeg.FS("readFile", "out.pcm"); } catch (_) {}
      try { ffmpeg.FS("unlink", "out.rgba"); } catch (_) {}
      try { ffmpeg.FS("unlink", "out.pcm"); } catch (_) {}

      const frameBytes = W * H * 4;
      const total = raw ? Math.floor(raw.length / frameBytes) : 0;

      if (total > 0 && myRun === runId) {
        const audioDur = scheduleAudio(pcm);
        const frameDelay = audioDur > 0 ? Math.max(15, (audioDur * 1000) / total) : 41;

        for (let i = 0; i < total && myRun === runId && jumpOffset < 0; i++) {
          while (!play && myRun === runId && jumpOffset < 0) await new Promise(r => setTimeout(r, 50));
          imgData.data.set(raw.subarray(i * frameBytes, (i + 1) * frameBytes));
          ctx.putImageData(imgData, 0, 0);
          drawn++;
          if (drawn % 4 === 1) msg.textContent = "Playing " + pct + "% | Frame " + drawn;
          await new Promise(r => setTimeout(r, frameDelay));
        }
      }
      offset = alignedEnd;
    }
    if (myRun === runId) msg.textContent = "Finished (" + drawn + " frames)";
  };
<\/script></body></html>`;

const doc = frame.contentDocument || frame.contentWindow.document;
doc.open(); doc.write(html); doc.close();
